insert into public.marketing_calendar_plans(id,meta) values ('noviembre-2026','{"title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "timezone": "America/Bogota", "start": "2026-11-01", "end": "2026-12-06", "scope": "4 reels + 15 posts de feed. 34 secuencias de stories del 3/11 al 6/12, adicionales al paquete. Fechas y horas propuestas; no es un programador de Instagram.", "strategy": [{"title": "Cuatro reels, cuatro trabajos", "body": "R01: recorrido POV para descubrimiento local. R02: presentador y tres motivos para asistir. R03: transformación antes/después para mostrar utilidad. R04: lista navideña y oferta para consulta o visita. Son hipótesis de producción para esta tienda, no formatos con viralidad garantizada."}, {"title": "Una campaña que acumula intención", "body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %."}, {"title": "Grabación que se puede ejecutar", "body": "Cuatro mañanas de rodaje propuestas, una por reel. Grabar video vertical propio 9:16, voz clara, subtítulos y producto desde el primer plano; revisar zonas cubiertas por la interfaz antes de exportar. Feed 4:5 y carruseles de 4–6 láminas; portada con una idea, cierre con una acción. Usar audio con derechos de uso comercial."}, {"title": "Horario de partida, no «mejor hora» probada", "body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Stories en tres ventanas, con cobertura extra en eventos. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta."}, {"title": "Medición útil para retail", "body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta."}, {"title": "Pauta después de validar la pieza", "body": "Sin gasto ni publicación automática desde este módulo. Propuesta: promover R02 para asistencia local antes del 14; R04 para consultas navideñas del 27 al 29. Separar Niquía de Santa Lucía y revisar radio real por desplazamiento; no fraccionar un presupuesto pequeño en muchos conjuntos. Escalar por consulta cualificada y compra verificable, no por seguidores baratos; presupuesto y anuncios requieren decisión posterior."}, {"title": "Productos reales, no catálogo cerrado", "body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden."}, {"title": "Revisión de Instagram: alcance y límite", "body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados."}, {"title": "Promociones con información clara", "body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir."}], "sources": [{"title": "Meta · Best Practices de Instagram", "url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"title": "Meta · Trial Reels", "url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. No añadir reels fuera del paquete."}, {"title": "Meta · Creatividad y pruebas", "url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"title": "Instagram de Importados · revisión manual pendiente", "url": "https://www.instagram.com/tiendasimportados/", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}]}'::jsonb) on conflict(id) do nothing;
