insert into public.marketing_calendar_items(id,plan_id,data) values ('P01','noviembre-2026','{"id": "P01", "date": "2026-11-04", "time": "18:30", "end_date": "2026-11-04", "kind": "post", "season": "comunidad", "title": "Así compartimos la natillada", "objective": "Convertir la actividad del 1 de noviembre en cercanía y reconocimiento local.", "caption": "Así se vivió nuestra natillada del 1 de noviembre 💛 Entre natilla, sonrisas y buenos momentos, seguimos conociendo a quienes hacen parte de Importados. Gracias por acompañarnos. ¿Estuviste por aquí? Cuéntanos cuál fue tu momento favorito. 🖤\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: «Así compartimos el 1 de noviembre» + foto real de la natillada.", "Foto de preparación o servicio: «Los mejores momentos se comparten».", "Dos momentos espontáneos de asistentes y equipo, con permisos.", "Cierre: «Gracias por acompañarnos. Esto apenas comienza»."], "assets": [], "checks": ["Recibir 5–8 fotos reales de la natillada; no sustituirlas por imágenes de otro evento.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Seleccionar fotos el 3/11; evitar presentar la natillada como un evento futuro.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('S1105','noviembre-2026','{"id": "S1105", "date": "2026-11-05", "time": "10:30", "end_date": "2026-11-05", "kind": "story", "season": "niquia", "title": "Stories: POV: entras por una cosa en Niquía", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Recompartir R01 con una pregunta relacionada.\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de tren navideño; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Recompartir R01 con una pregunta relacionada.", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('R01','noviembre-2026','{"id": "R01", "date": "2026-11-05", "time": "18:30", "end_date": "2026-11-05", "kind": "reel", "season": "niquia", "title": "POV: entras por una cosa en Niquía", "objective": "Descubrimiento local: mostrar recorrido y variedad con una situación reconocible.", "caption": "POV: entras por una cosa… y empiezas a hacer tu lista 💛🖤 Ya estamos abiertos en Niquía: Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nNos visitas de 9:00 a. m. a 8:00 p. m. Y el 14 y 15 de noviembre celebramos la gran inauguración.\n¿Con quién vendrías? Envíale este recorrido.\n#Niquía #Bello #TiendasImportados", "outline": ["Duración objetivo 22–25 s. Grabar el recorrido real, no una sucesión de pósteres.", "Primera imagen con persona entrando y producto visible, sin introducción de logo.", "Subtítulos, sonido propio/uso comercial autorizado y una sola llamada a compartir."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/01-licuadora.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "script": [{"time": "0–2 s", "visual": "Mano abre la puerta y toma un producto.", "voice": "Vine por una cosita…", "text": "POV: entras por una cosa"}, {"time": "2–7 s", "visual": "Tres cortes: árbol, Papá Noel, detalle de mesa.", "voice": "…y terminé haciendo mi lista de Navidad.", "text": "Árbol / detalles / regalos"}, {"time": "7–13 s", "visual": "Presentador muestra hogar y navidad, referencias distintas.", "voice": "En Importados Niquía encuentras ideas para tu casa y para regalar.", "text": "Niquía, ya estamos abiertos"}, {"time": "13–19 s", "visual": "Fachada completa y dirección legible.", "voice": "Estamos en el edificio Valkiria, Diagonal 55 Av 38-33.", "text": "Diagonal 55 Av 38-33 · Valkiria"}, {"time": "19–25 s", "visual": "Presentador señala cartel con fechas.", "voice": "Ven a conocernos y celebra con nosotros el 14 y 15 de noviembre.", "text": "Envíalo a quien vendría contigo"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Grabar 4/11 por la mañana. Gancho alternativo sobre el mismo montaje: «Niquía: mira lo que encontramos en Valkiria». No cuenta como un quinto reel.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('S1106','noviembre-2026','{"id": "S1106", "date": "2026-11-06", "time": "10:30", "end_date": "2026-11-06", "kind": "story", "season": "niquia", "title": "Stories: Ya estamos en Niquía: guarda cómo llegar", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Video propio de Papá Noel; mostrar uso o detalle real, sin afirmar funciones no probadas.\n13:00 · Recompartir P02 con una pregunta relacionada.\n18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias.", "outline": ["10:30 · Video propio de Papá Noel; mostrar uso o detalle real, sin afirmar funciones no probadas.", "13:00 · Recompartir P02 con una pregunta relacionada.", "18:30 · Respuesta útil a una consulta real + enlace a WhatsApp; comprobar referencia, sede y existencias."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('P02','noviembre-2026','{"id": "P02", "date": "2026-11-06", "time": "18:30", "end_date": "2026-11-06", "kind": "post", "season": "niquia", "title": "Ya estamos en Niquía: guarda cómo llegar", "objective": "Resolver la fricción de ubicación antes de invitar al evento.", "caption": "¡Niquía, ya puedes visitarnos! 💛 Estamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nHorario de atención: 9:00 a. m. a 8:00 p. m.\nY el 14 y 15 de noviembre celebraremos nuestra gran inauguración. Guarda esta dirección y compártela con quien vendría contigo.\n#TiendasImportados #Niquía #Bello", "outline": ["Fachada actual: «Ya estamos abiertos en Niquía».", "Dirección completa con «edificio Valkiria» en alto contraste.", "Mapa sencillo con pin revisado; no inventar tiempo a pie desde el Metro.", "Horario 9–20 + fechas 14/15 + CTA guardar."], "assets": [], "checks": ["Comprobar pin exacto y foto de entrada; no publicar ruta desde la estación sin recorrerla."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "", "revision": 1}'::jsonb) on conflict(id) do nothing;
