insert into public.marketing_calendar_items(id,plan_id,data) values ('P03','noviembre-2026','{"id": "P03", "date": "2026-11-08", "time": "18:30", "end_date": "2026-11-08", "kind": "post", "season": "navidad", "title": "¿Tu Navidad es dorada o plateada?", "objective": "Conseguir guardados y preferencias para preparar la selección de Black Friday.", "caption": "¿Team dorado o team plateado? ✨ Los detalles cambian el ambiente de tu casa. Desliza, elige tu estilo y guarda tus favoritos para empezar a preparar Navidad.\nCuéntanos tu elección y te ayudamos a consultar las referencias disponibles. 💛🖤\n#NavidadEnCasa #TiendasImportados #DecoraciónNavideña", "outline": ["Portada con contraste de piezas doradas y plateadas.", "Foto dorada en un ambiente real, no solo estantería.", "Foto plateada en el mismo encuadre.", "Composición con figura navideña y árbol; referencias por confirmar.", "Cierre: «Guarda tu estilo. ¿Dorado o plateado?»"], "assets": ["/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/08-arboles.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar las fotos recibidas como referencias; producir composiciones nuevas, sin atribuir material o función no confirmados.", "revision": 1}'::jsonb) on conflict(id) do nothing;
