insert into public.marketing_calendar_items(id,plan_id,data) values ('P04','noviembre-2026','{"id": "P04", "date": "2026-11-10", "time": "18:30", "end_date": "2026-11-10", "kind": "post", "season": "niquia", "title": "La fiesta de inauguración ya tiene fecha", "objective": "Dar razones concretas para asistir sin inventar programación.", "caption": "¡El 14 y 15 de noviembre celebramos en Niquía! 💛🖤 Tendremos música en vivo, la trova de Toto y Sirirí y una presentación de la imitadora de Arelys Henao de Yo Me Llamo.\nTambién habrá 20 % de descuento en gran parte de la tienda y actividades para compartir.\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nMuy pronto te compartiremos horarios y condiciones. ¡Reserva las fechas!", "outline": ["Portada: «Gran inauguración · 14 y 15 de noviembre».", "Talento: Toto y Sirirí / imitadora de Arelys Henao de Yo Me Llamo, con fotos autorizadas.", "Descuento: «20 % en gran parte de la tienda» + exclusiones legibles.", "Dirección y CTA: «Ven acompañado». No atribuir cada artista a ambos días."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorizar fotografías, nombres artísticos y uso promocional de los artistas."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('S1111','noviembre-2026','{"id": "S1111", "date": "2026-11-11", "time": "10:30", "end_date": "2026-11-11", "kind": "story", "season": "niquia", "title": "Plan para el fin de semana", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · «14 y 15: agenda la inauguración».\n13:00 · Recompartir R02 + sticker de cuenta regresiva a apertura de tienda, no a shows sin hora.\n18:30 · Dirección Valkiria + enlace de Maps.", "outline": ["10:30 · «14 y 15: agenda la inauguración».", "13:00 · Recompartir R02 + sticker de cuenta regresiva a apertura de tienda, no a shows sin hora.", "18:30 · Dirección Valkiria + enlace de Maps."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('R02','noviembre-2026','{"id": "R02", "date": "2026-11-11", "time": "18:30", "end_date": "2026-11-11", "kind": "reel", "season": "niquia", "title": "Tres razones para venir a la inauguración", "objective": "Invitación humana con beneficio y ubicación; premiación solo con bases.", "caption": "¡Niquía, tenemos plan para el 14 y 15 de noviembre! 💛 Música, trova, variedad y 20 % de descuento en gran parte de la tienda.\nNos acompañarán Toto y Sirirí y la imitadora de Arelys Henao de Yo Me Llamo. Consulta la programación y condiciones en nuestras stories.\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello. Envíale este plan a quien te acompaña. 🖤", "outline": ["Duración 28–32 s; presentador en fachada + pruebas visuales de tienda.", "Versión principal no depende de publicar bases de rifas.", "Si se aprueban premios, usar stories/P05; no saturar el reel con todas las condiciones."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorización del material promocional de artistas."], "script": [{"time": "0–3 s", "visual": "Presentador frente a fachada, gesto de tres razones.", "voice": "Niquía, te damos tres razones para salir este 14 y 15.", "text": "14 y 15 NOV · Niquía"}, {"time": "3–10 s", "visual": "Cortes de presentador y artes autorizados de artistas.", "voice": "Uno: música en vivo, Toto y Sirirí y la imitadora de Arelys Henao de Yo Me Llamo.", "text": "Música y trova · horarios por anunciar"}, {"time": "10–17 s", "visual": "Pasillos/productos reales, rótulo descuento.", "voice": "Dos: 20 % de descuento en gran parte de la tienda.", "text": "20 % · consulta exclusiones y condiciones"}, {"time": "17–24 s", "visual": "Persona compara dos detalles y sonríe.", "voice": "Tres: descubrir ideas para tu casa y preparar Navidad.", "text": "Ven a conocer la variedad"}, {"time": "24–32 s", "visual": "Fachada, dirección y tarjeta final.", "voice": "Te esperamos en Valkiria, Diagonal 55 Av 38-33. Guarda las fechas y ven acompañado.", "text": "14–15 NOV · comparte este plan"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Grabar 9/11 y validar 10/11. No usar grabaciones de la cantante original como si se presentara en Importados.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('S1112','noviembre-2026','{"id": "S1112", "date": "2026-11-12", "time": "10:30", "end_date": "2026-11-12", "kind": "story", "season": "niquia", "title": "Rifa y concurso: solo con bases", "objective": "Conversación diaria y apoyo al calendario; responder sin prometer stock ni horarios de actividades no confirmados.", "caption": "10:30 · Premios reales, solo tras aprobar bases.\n13:00 · Compra en tienda + seguir Instagram; enlazar reglas completas.\n18:30 · Concurso: $500.000 efectivo + $500.000 tienda; cupos/edades según bases. Si faltan, reemplazar por recorrido de tienda.", "outline": ["10:30 · Premios reales, solo tras aprobar bases.", "13:00 · Compra en tienda + seguir Instagram; enlazar reglas completas.", "18:30 · Concurso: $500.000 efectivo + $500.000 tienda; cupos/edades según bases. Si faltan, reemplazar por recorrido de tienda."], "assets": [], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo."], "script": [], "format": "Secuencia · 3 stories · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Horarios propuestos de Bogotá. Stories orgánicas adicionales al paquete de 4 reels + 15 posts; requieren cobertura del equipo, no piezas de feed extra.", "revision": 1}'::jsonb) on conflict(id) do nothing;
insert into public.marketing_calendar_items(id,plan_id,data) values ('P05','noviembre-2026','{"id": "P05", "date": "2026-11-12", "time": "18:30", "end_date": "2026-11-12", "kind": "post", "season": "niquia", "title": "Premios y concurso: guía para participar", "objective": "Aclarar incentivos con reglas completas antes del fin de semana.", "caption": "La inauguración de Niquía también viene con premios 💛 Habrá una rifa de una moto y patinetes eléctricos. Para participar debes comprar en tienda y seguir a @tiendasimportados; consulta las bases completas antes de participar.\nAdemás, el concurso «Culi chupado» tendrá un premio de $500.000 en efectivo y $500.000 para gastar en la tienda.\nNos vemos el 14 y 15 de noviembre en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nLa mecánica completa, los horarios y las condiciones deben acompañar esta publicación.", "outline": ["Portada: «Inauguración con premios · 14 y 15».", "Foto del premio real: moto AKT; confirmar denominación «Special 110X» antes de usarla.", "Patinetes eléctricos: confirmar cantidad y modelos reales.", "Rifa: compra en tienda + sigue Instagram + bases completas visibles.", "Concurso «Culi chupado»: $500.000 efectivo + $500.000 consumo; añadir requisitos aprobados.", "Última lámina: fechas/horarios del sorteo y enlace o QR a bases aprobadas."], "assets": [], "checks": ["Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo.", "Sustituir la última frase editorial del caption por el enlace a bases definitivas; no publicar el borrador como anuncio."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Si no hay bases aprobadas el 11/11, reemplazar por carrusel de ubicación y ambiente. No promover la rifa incompleta.", "revision": 1}'::jsonb) on conflict(id) do nothing;
