insert into public.marketing_calendar_items(id,plan_id,data) values ('P08','noviembre-2026','{"id": "P08", "date": "2026-11-17", "time": "18:30", "end_date": "2026-11-17", "kind": "post", "season": "comunidad", "title": "Gracias por una inauguración para recordar", "objective": "Conservar confianza y convertir asistentes en comunidad.", "caption": "¡Gracias por celebrar con nosotros, Niquía! 💛🖤 Nos quedamos con las sonrisas, la música y cada persona que pasó a conocernos este 14 y 15 de noviembre.\nDesliza para revivir algunos momentos. Si estuviste, cuéntanos qué fue lo que más disfrutaste. Seguimos aquí para acompañarte con variedad y nuevas ideas para tu hogar.\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: foto propia de mayor emoción + «Gracias, Niquía».", "Ambiente y equipo.", "Trovadores y presentación artística realmente realizada.", "Actividad del concurso solo si fue realizada y se autorizan imágenes.", "Cierre: foto de fachada + «Nos seguimos encontrando aquí»."], "assets": [], "checks": ["Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable.", "Verificar qué actividades sí ocurrieron; no anunciar ganadores sin resultado y autorización confirmados."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "No convertir la entrega de premios en promesa futura; si no está resuelta, omitirla del carrusel.", "revision": 1}'::jsonb) on conflict(id) do nothing;
