insert into public.marketing_calendar_items(id,plan_id,data) values ('R03','noviembre-2026','{"id": "R03", "date": "2026-11-18", "time": "18:30", "end_date": "2026-11-18", "kind": "reel", "season": "navidad", "title": "De rincón vacío a rincón navideño", "objective": "Demostrar transformación y uso real para provocar guardados y consultas.", "caption": "El mismo rincón, otra sensación 🎄✨ Un árbol, una figura y detalles que combinan: así empezamos a preparar Navidad.\n¿Lo harías dorado o plateado? Guarda la idea y consulta las referencias disponibles. 💛🖤\n#DecoraciónNavideña #TiendasImportados #NavidadEnCasa", "outline": ["Duración 20–24 s; cámara fija, antes/después del mismo espacio.", "Las fotos recibidas sirven para escoger referencias; hace falta video real de montaje.", "No atribuir luces, movimiento, medidas o accesorios a productos sin comprobarlos."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/03-tren-navideno.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [{"time": "0–2 s", "visual": "Rincón vacío → corte de un segundo al resultado.", "voice": "¿Y si tu rincón de Navidad empezara aquí?", "text": "Mira el antes y el después"}, {"time": "2–7 s", "visual": "Colocar árbol en el encuadre fijo.", "voice": "Empezamos con la base.", "text": "1. Elige tu árbol"}, {"time": "7–12 s", "visual": "Añadir Papá Noel y detalle dorado o plateado.", "voice": "Sumamos un personaje y elegimos un estilo.", "text": "2. Un personaje · 3. Tu estilo"}, {"time": "12–17 s", "visual": "Primeros planos de textura y composición; tren solo probado.", "voice": "Los detalles hacen el resto.", "text": "Dorado o plateado, tú eliges"}, {"time": "17–24 s", "visual": "Plano final igual al inicial + persona observa resultado.", "voice": "Guarda esta idea y cuéntanos cuál harías en tu casa.", "text": "Guárdalo para tu Navidad"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Grabar 16/11 sin rótulos de inauguración; medir guardados/alcance. No subir como plantilla con fotos estáticas únicamente.", "revision": 1}'::jsonb) on conflict(id) do nothing;
