insert into public.marketing_calendar_items(id,plan_id,data) values ('P11','noviembre-2026','{"id": "P11", "date": "2026-11-24", "time": "18:30", "end_date": "2026-11-24", "kind": "post", "season": "black-friday", "title": "Black Friday: fechas y condiciones claras", "objective": "Quitar dudas de vigencia y alcance antes de la promoción.", "caption": "Anota las fechas: 27, 28 y 29 de noviembre 🖤💛 En Importados tendremos 20 % de descuento en toda la tienda.\nUna oportunidad para preparar tu Navidad y elegir esos detalles para tu hogar.\nConsulta las condiciones vigentes de la promoción. Escríbenos al WhatsApp 312 706 2214 o visítanos en tienda.\nNiquía: Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello. Santa Lucía: Cr. 87 # 47 DD 50, Medellín.", "outline": ["Portada: «Black Friday · 27 al 29 · 20 %».", "Qué incluye: toda la tienda, según alcance y sedes confirmados.", "Cómo comprar: atención en sede y consulta de productos por WhatsApp; no prometer reserva o envío gratis.", "Condiciones completas: vigencia y horario, base de descuento, disponibilidad y acumulabilidad confirmadas.", "Direcciones y WhatsApp."], "assets": [], "checks": ["Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "", "revision": 1}'::jsonb) on conflict(id) do nothing;
