insert into public.marketing_calendar_items(id,plan_id,data) values ('R04','noviembre-2026','{"id": "R04", "date": "2026-11-26", "time": "18:30", "end_date": "2026-11-26", "kind": "reel", "season": "black-friday", "title": "La lista navideña se prepara para Black Friday", "objective": "Generar intención de visita para el 27–29 con demostración y oferta clara.", "caption": "Tu lista de Navidad tiene cita en Importados 🖤💛 Mañana empieza Black Friday: del 27 al 29 de noviembre, 20 % de descuento en toda la tienda.\nÁrboles, decoración y detalles para tu hogar: guarda tus favoritos y consulta las condiciones de la promoción.\nEscríbenos al WhatsApp 312 706 2214 o visítanos en tienda.\n#BlackFriday #TiendasImportados #Navidad", "outline": ["Duración 22–26 s. Producto en primer plano desde el primer segundo.", "Montaje de lista real, sin precios que no se hayan validado.", "Esta pieza abre la campaña; no inventar existencias escasas, reserva ni acumulación con promociones anteriores."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/07-tren-navideno-set.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/01-licuadora.jpeg", "/marketing-assets/02-olla-arrocera.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración."], "script": [{"time": "0–3 s", "visual": "Persona sostiene lista y árbol/producto ocupa el cuadro.", "voice": "Antes de comprar tu Navidad, mira estas fechas.", "text": "27–29 NOV · Black Friday"}, {"time": "3–10 s", "visual": "Mano marca lista con árbol, Papá Noel y decoración.", "voice": "Árbol, decoración, detalles para regalar… arma tu selección.", "text": "Tu lista navideña"}, {"time": "10–17 s", "visual": "Corte a hogar: olla/licuadora y vuelta a decoración.", "voice": "Del 27 al 29 tenemos 20 % de descuento en toda la tienda.", "text": "20 % · toda la tienda · condiciones vigentes"}, {"time": "17–22 s", "visual": "Fachada y equipo real.", "voice": "Consulta tus favoritos y ven con tu lista.", "text": "Consulta disponibilidad por WhatsApp"}, {"time": "22–26 s", "visual": "Tarjeta clara fecha / sedes.", "voice": "Guarda las fechas. ¡Te esperamos en Importados!", "text": "27, 28 y 29 NOV · guarda este reel"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Grabar 23/11, revisar 24/11 y cerrar edición 25/11. No pautar antes de aprobar las condiciones. El anuncio pagado requiere presupuesto y publicación separadas.", "revision": 1}'::jsonb) on conflict(id) do nothing;
