insert into public.marketing_calendar_items(id,plan_id,data) values ('P15','noviembre-2026','{"id": "P15", "date": "2026-12-01", "time": "18:30", "end_date": "2026-12-01", "kind": "post", "season": "navidad", "title": "Diciembre empieza en casa", "objective": "Cambiar de descuento a inspiración y compra de temporada.", "caption": "¡Hola, diciembre! 🎄💛 Empieza el mes de los encuentros, los regalos y esos detalles que hacen tu casa más tuya.\nDesliza y arma tu lista: un rincón para decorar, algo para compartir y un detalle para regalar.\nCuéntanos qué estás buscando y revisamos las opciones disponibles. 🖤\n#Navidad #TiendasImportados #Regalos", "outline": ["Portada: «Diciembre empieza en casa».", "Decorar: árboles, Papá Noel y detalles de mesa.", "Compartir: opciones de hogar, sin afirmar funciones técnicas no verificadas.", "Regalar: selección real disponible para distintos gustos; sin precios inventados.", "Lista guardable con casillas: decorar / compartir / regalar."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/02-olla-arrocera.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "No arrastrar 20 % después del 29/11. La campaña de diciembre necesita una nueva planeación; esta pieza abre la temporada.", "revision": 1}'::jsonb) on conflict(id) do nothing;
