-- Importados only. Additive editorial calendar; no WhatsApp/customer mutations.
begin;
create table if not exists public.marketing_calendar_plans (
 id text primary key, meta jsonb not null check(jsonb_typeof(meta)='object'), created_at timestamptz not null default now()
);
create table if not exists public.marketing_calendar_items (
 id text primary key check(id ~ '^[PRESA][0-9]{2,4}$'),
 plan_id text not null references public.marketing_calendar_plans(id),
 data jsonb not null check(jsonb_typeof(data)='object' and data->>'id'=id),
 revision integer not null default 1 check(revision>0),
 updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id)
);
create table if not exists public.marketing_share_links (
 id uuid primary key default gen_random_uuid(), plan_id text not null references public.marketing_calendar_plans(id),
 label text not null check(char_length(label) between 2 and 100),
 token_hash text not null unique check(token_hash ~ '^[0-9a-f]{64}$'),
 created_at timestamptz not null default now(), expires_at timestamptz not null,
 revoked_at timestamptz, created_by uuid not null references public.profiles(id),
 check(expires_at>created_at)
);
alter table public.marketing_calendar_plans enable row level security;
alter table public.marketing_calendar_items enable row level security;
alter table public.marketing_share_links enable row level security;
revoke all on public.marketing_calendar_plans,public.marketing_calendar_items,public.marketing_share_links from public,anon,authenticated;
grant select on public.marketing_calendar_plans,public.marketing_calendar_items to authenticated;
grant all on public.marketing_calendar_plans,public.marketing_calendar_items,public.marketing_share_links to service_role;
drop policy if exists marketing_plan_admin_read on public.marketing_calendar_plans;
create policy marketing_plan_admin_read on public.marketing_calendar_plans for select to authenticated using(public.is_admin());
drop policy if exists marketing_items_admin_read on public.marketing_calendar_items;
create policy marketing_items_admin_read on public.marketing_calendar_items for select to authenticated using(public.is_admin());
commit;
